msgs, err := ch.Consume("orders", "", false, false, false, false, nil)
if err != nil { return fmt.Errorf("consume: %w", err) }
go func() {
    for d := range msgs {
        if err := handle(d.Body); err != nil {
            d.Nack(false, true)
            continue
        }
        d.Ack(false)
    }
}()
